//! Zstandard frame and block decoder (RFC 8878 Section 3).

use std::io;

use super::bits::{ForwardByteReader, ReverseBitReader};
use super::fse::{self, FseTable};
use super::huf::HufTable;

const ZSTD_MAGIC: u32 = 0xFD2FB528;
const MIN_WINDOW_LOG: u32 = 10;
const MAX_WINDOW_SIZE: u64 = 1 << 27; // 128 MB cap for safety
/// Maximum decoded size of one zstd block. Used to size the frame-lifetime
/// literals scratch and to reserve output headroom for the SIMD wildcopy.
const ZSTD_BLOCKSIZE_MAX: usize = 128 * 1024;

// ---------------------------------------------------------------------------
// Frame header
// ---------------------------------------------------------------------------

struct FrameHeader {
    window_size: u64,
    content_size: Option<u64>,
    dict_id: Option<u32>,
    content_checksum: bool,
}

fn parse_frame_header(r: &mut ForwardByteReader) -> io::Result<FrameHeader> {
    let magic = r.read_u32_le()?;
    if magic != ZSTD_MAGIC {
        // Check for skippable frame (0x184D2A5X).
        if (magic & 0xFFFFFFF0) == 0x184D2A50 {
            let size = r.read_u32_le()? as usize;
            r.skip(size)?;
            return Err(io::Error::new(io::ErrorKind::Other, "zstd: skippable frame"));
        }
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zstd: invalid magic number {:08x}", magic),
        ));
    }

    let descriptor = r.read_u8()?;
    let dict_id_flag = descriptor & 3;
    let content_checksum = (descriptor >> 2) & 1 != 0;
    let _reserved = (descriptor >> 3) & 1;
    let _unused = (descriptor >> 4) & 1;
    let single_segment = (descriptor >> 5) & 1 != 0;
    let fcs_field_size_flag = (descriptor >> 6) & 3;

    // Window descriptor (absent if single_segment).
    let window_size = if !single_segment {
        let wd = r.read_u8()?;
        let exponent = (wd >> 3) as u32;
        let mantissa = (wd & 7) as u64;
        let base = 1u64 << (MIN_WINDOW_LOG + exponent);
        base + (base >> 3) * mantissa
    } else {
        0 // Will be set from content_size.
    };

    // Dictionary ID.
    let dict_id = match dict_id_flag {
        0 => None,
        1 => Some(r.read_u8()? as u32),
        2 => Some(r.read_u16_le()? as u32),
        3 => Some(r.read_u32_le()?),
        _ => unreachable!(),
    };

    // Frame Content Size.
    let fcs_field_size = match fcs_field_size_flag {
        0 => {
            if single_segment { 1 } else { 0 }
        }
        1 => 2,
        2 => 4,
        3 => 8,
        _ => unreachable!(),
    };
    let content_size = match fcs_field_size {
        0 => None,
        1 => Some(r.read_u8()? as u64),
        2 => Some(r.read_u16_le()? as u64 + 256),
        4 => Some(r.read_u32_le()? as u64),
        8 => Some(r.read_u64_le()?),
        _ => unreachable!(),
    };

    let window_size = if single_segment {
        content_size.unwrap_or(0)
    } else {
        window_size
    };

    Ok(FrameHeader {
        window_size: window_size.min(MAX_WINDOW_SIZE),
        content_size,
        dict_id,
        content_checksum,
    })
}

// ---------------------------------------------------------------------------
// Block decoding
// ---------------------------------------------------------------------------

/// Decode an entire zstd frame, appending decompressed data to `output`.
/// Returns the number of input bytes consumed.
pub fn decode_frame(data: &[u8], output: &mut Vec<u8>) -> io::Result<usize> {
    let mut r = ForwardByteReader::new(data);
    let header = match parse_frame_header(&mut r) {
        Err(e) if e.kind() == io::ErrorKind::Other => {
            // Skippable frame — return bytes consumed.
            return Ok(r.position());
        }
        result => result?,
    };

    if header.dict_id.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "zstd: dictionary decoding not supported",
        ));
    }

    if let Some(cs) = header.content_size {
        output.reserve(cs as usize);
    }

    let out_start = output.len();

    // Persistent Huffman table (reused across blocks with Treeless mode).
    let mut huf_table: Option<HufTable> = None;
    // Persistent FSE tables (reused with Repeat mode).
    let mut ll_table: Option<FseTable> = None;
    let mut of_table: Option<FseTable> = None;
    let mut ml_table: Option<FseTable> = None;
    // Repeat offsets.
    let mut rep_offsets = [1u32, 4, 8];
    // Frame-lifetime literals scratch. Sized to hold any one block's
    // decompressed literals plus a 32-byte trailing dead zone used by the
    // SIMD wildcopy in the sequence loop. Reused across all blocks in the
    // frame so we allocate once per decode instead of twice per block.
    let mut literals_buf: Vec<u8> = Vec::with_capacity(ZSTD_BLOCKSIZE_MAX + 32);

    loop {
        let block_header = r.read_u24_le()?;
        let last_block = (block_header & 1) != 0;
        let block_type = (block_header >> 1) & 3;
        let block_size = (block_header >> 3) as usize;

        match block_type {
            0 => {
                // Raw block.
                let raw = r.read_bytes(block_size)?;
                output.extend_from_slice(raw);
            }
            1 => {
                // RLE block.
                let byte = r.read_u8()?;
                output.resize(output.len() + block_size, byte);
            }
            2 => {
                // Compressed block.
                let block_data = r.read_bytes(block_size)?;
                decode_compressed_block(
                    block_data,
                    output,
                    &mut huf_table,
                    &mut ll_table,
                    &mut of_table,
                    &mut ml_table,
                    &mut rep_offsets,
                    header.window_size,
                    &mut literals_buf,
                )?;
            }
            3 => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zstd: reserved block type",
                ));
            }
            _ => unreachable!(),
        }

        if last_block {
            break;
        }
    }

    // Content checksum (xxhash64, lower 32 bits).
    if header.content_checksum {
        let expected = r.read_u32_le()?;
        let actual = xxhash(&output[out_start..]);
        if actual != expected {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zstd: content checksum mismatch (expected {:08x}, got {:08x})", expected, actual),
            ));
        }
    }

    // Verify content size if declared.
    if let Some(cs) = header.content_size {
        let produced = (output.len() - out_start) as u64;
        if produced != cs {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zstd: content size mismatch (header={}, produced={})", cs, produced),
            ));
        }
    }

    Ok(r.position())
}

// ---------------------------------------------------------------------------
// Compressed block
// ---------------------------------------------------------------------------

fn decode_compressed_block(
    data: &[u8],
    output: &mut Vec<u8>,
    huf_table: &mut Option<HufTable>,
    ll_table: &mut Option<FseTable>,
    of_table: &mut Option<FseTable>,
    ml_table: &mut Option<FseTable>,
    rep_offsets: &mut [u32; 3],
    _window_size: u64,
    literals_buf: &mut Vec<u8>,
) -> io::Result<()> {
    let mut r = ForwardByteReader::new(data);

    // --- Literals Section ---
    // Decode directly into the frame-lifetime scratch (reused across blocks)
    // so we avoid one Vec alloc per block. `decode_literals_section_into`
    // sets the length to the real literal count.
    let lit_total = decode_literals_section_into(&mut r, huf_table, literals_buf)?;
    // Pad with 32 trailing dead-zone bytes so the per-sequence 16-byte
    // wildcopy in the hot loop can safely over-read past the last literal
    // without the caller having to branch on "short literal".
    literals_buf.resize(lit_total + 32, 0);
    let literals: &[u8] = literals_buf;

    // Reserve the worst-case output for this block upfront so neither the
    // literal copies nor the per-sequence match wildcopy need to re-check
    // capacity. The `+ 32` is dead-zone padding for the SIMD wildcopy
    // overshoot in `cpu_features::copy_match_unchecked`.
    output.reserve(ZSTD_BLOCKSIZE_MAX + 32);

    // --- Sequences Section ---
    let seq_data = &data[r.position()..];
    if seq_data.is_empty() {
        // No sequences — all data is literals.
        output.extend_from_slice(&literals[..lit_total]);
        return Ok(());
    }

    let mut sr = ForwardByteReader::new(seq_data);
    let num_sequences = decode_sequence_count(&mut sr)?;

    if num_sequences == 0 {
        output.extend_from_slice(&literals[..lit_total]);
        return Ok(());
    }

    // Decode sequence section header (FSE table modes).
    let mode_byte = sr.read_u8()?;
    let ll_mode = (mode_byte >> 6) & 3;
    let of_mode = (mode_byte >> 4) & 3;
    let ml_mode = (mode_byte >> 2) & 3;

    decode_fse_table_mode(&mut sr, ll_mode, ll_table, 35, 9, fse::predefined_litlen_table)?;
    decode_fse_table_mode(&mut sr, of_mode, of_table, 31, 8, fse::predefined_offset_table)?;
    decode_fse_table_mode(&mut sr, ml_mode, ml_table, 52, 9, fse::predefined_matchlen_table)?;

    let ll_t = ll_table.as_ref().unwrap();
    let of_t = of_table.as_ref().unwrap();
    let ml_t = ml_table.as_ref().unwrap();

    // Decode sequences from backward bitstream.
    let bitstream = &seq_data[sr.position()..];
    let mut bits = ReverseBitReader::new(bitstream)?;
    bits.skip_padding_bits()?;

    // Initialize FSE states (order per RFC 8878 Section 3.1.2.1.2.4).
    let mut ll_state = bits.get_bits(ll_t.accuracy_log);
    let mut of_state = bits.get_bits(of_t.accuracy_log);
    let mut ml_state = bits.get_bits(ml_t.accuracy_log);

    // Cache the literals pointer + output pointer once so the per-sequence loop
    // body is pure pointer arithmetic. The literals buffer has 32 bytes of
    // trailing zero padding (see decode_compressed_block top), so a 16-byte
    // wildcopy read past the last literal is safe and the value is discarded
    // via the tracked `lit_pos`/`lit_total` cursor. The upfront
    // `ZSTD_BLOCKSIZE_MAX + 32` reservation guards the destination overshoot.
    //
    // `dst_off` tracks the logical end of the output for this block. We set
    // `output.len()` exactly once at the end of the loop instead of every
    // sequence, saving ~1% of total Ir.
    let lit_ptr = literals.as_ptr();
    let base = output.as_mut_ptr();
    let mut lit_pos = 0usize;
    let mut dst_off = output.len();
    // Peel off the last iteration so the state-update branch (`if i <
    // num_sequences - 1`) disappears from the hot body — we update state on
    // every iteration except the last, and the peeled tail has no update.
    let main_iters = num_sequences - 1;
    for _ in 0..main_iters {
        let r = decode_one_sequence(
            of_t, ml_t, ll_t,
            &mut of_state, &mut ml_state, &mut ll_state,
            &mut bits,
            lit_ptr, base, lit_total, &mut lit_pos, &mut dst_off,
            rep_offsets,
            true,
        )?;
        debug_assert!(r);
    }
    // Final sequence: no trailing state update.
    decode_one_sequence(
        of_t, ml_t, ll_t,
        &mut of_state, &mut ml_state, &mut ll_state,
        &mut bits,
        lit_ptr, base, lit_total, &mut lit_pos, &mut dst_off,
        rep_offsets,
        false,
    )?;

    // Commit the accumulated output length in one shot.
    unsafe { output.set_len(dst_off); }

    // Append remaining literals after all sequences. Use the tracked real
    // literal length (`lit_total`) rather than `literals.len()` so we don't
    // copy the trailing 32-byte wildcopy dead-zone.
    if lit_pos < lit_total {
        output.extend_from_slice(&literals[lit_pos..lit_total]);
    }

    Ok(())
}

/// Decode one sequence from the FSE-driven backward bit stream and execute
/// its literal+match copies into `output_base`. Centralized into a single
/// `#[inline(always)]` helper so the main loop body and peeled final
/// iteration share the same compiled code.
///
/// `update_state`: when true, run the trailing `ensure_bits(26) + 3x
/// next_state_fast` to advance the FSE states for the next iteration.
///
/// # Safety
/// * `lit_ptr` must point into a literal buffer of at least `lit_total + 16`
///   valid bytes (the trailing 16 are wildcopy padding).
/// * `output_base` must point into a buffer with at least 128 KiB + 32 bytes
///   of headroom at `*dst_off` (the upfront block reservation).
#[inline(always)]
#[allow(clippy::too_many_arguments)]
fn decode_one_sequence(
    of_t: &FseTable,
    ml_t: &FseTable,
    ll_t: &FseTable,
    of_state: &mut u32,
    ml_state: &mut u32,
    ll_state: &mut u32,
    bits: &mut ReverseBitReader,
    lit_ptr: *const u8,
    output_base: *mut u8,
    lit_total: usize,
    lit_pos: &mut usize,
    dst_off: &mut usize,
    rep_offsets: &mut [u32; 3],
    update_state: bool,
) -> io::Result<bool> {
    // 1. Peek symbols from current FSE states.
    let of_code = of_t.symbol(*of_state) as u32;
    let ml_code = ml_t.symbol(*ml_state);
    let ll_code = ll_t.symbol(*ll_state);

    // 2. Read extra bits in order: Offset, MatchLength, LitLength
    // (RFC 8878 3.1.2.1.2.4). When the combined extras fit in the
    // 56-bit window, do one refill and three fast reads — saves two
    // refill branches per sequence and stacks cleanly with the later
    // `ensure_bits(26)` for the state update.
    //
    // SAFETY: `ml_code`/`ll_code` come from FSE tables with max symbol
    // 52/35, so both are in range of MATCHLEN_TABLE / LITLEN_TABLE.
    let (ml_base, ml_extra) = unsafe { *fse::MATCHLEN_TABLE.get_unchecked(ml_code as usize) };
    let (ll_base, ll_extra) = unsafe { *fse::LITLEN_TABLE.get_unchecked(ll_code as usize) };
    let extras_total = of_code + ml_extra as u32 + ll_extra as u32;
    let (offset_value, match_len, lit_len) = if extras_total <= 56 {
        bits.ensure_bits(extras_total);
        // Zero-bit reads are defined (shift wrap + zero mask). When
        // of_code == 0: (1 << 0) + 0 == 1, matching the "offset_value = 1"
        // special case without a branch.
        let of_extra_val = bits.get_bits_fast(of_code);
        let offset_value = (1u32 << of_code) + of_extra_val;
        let ml_extra_val = bits.get_bits_fast(ml_extra as u32);
        let match_len = (ml_base + ml_extra_val) as usize;
        let ll_extra_val = bits.get_bits_fast(ll_extra as u32);
        let lit_len = (ll_base + ll_extra_val) as usize;
        (offset_value, match_len, lit_len)
    } else {
        // Fallback for pathological windowLog + max extras combos.
        let offset_value = (1u32 << of_code) + bits.get_bits(of_code);
        let match_len = (ml_base + bits.get_bits(ml_extra as u32)) as usize;
        let lit_len = (ll_base + bits.get_bits(ll_extra as u32)) as usize;
        (offset_value, match_len, lit_len)
    };

    // 3. Resolve offset (handles repeat offsets per RFC 8878 3.1.2.1.3).
    let offset = resolve_offset(offset_value, rep_offsets, lit_len);

    // 4. Execute: copy literals, then copy match. The upfront `output.reserve`
    // and the 32-byte literals padding let us use raw pointers without
    // re-checking capacity per iteration. Both safety checks are collapsed
    // into one `|`-combined test with a cold error helper so the hot body
    // gets a single branch that the predictor rings like a dial tone.
    let cur = *dst_off;
    let post_lit = cur + lit_len;
    let off = offset as usize;
    // Branchless combined check: any of the four bad conditions sets the
    // `err_mask` to nonzero; we branch once on the OR. Using `|` (not `||`)
    // so the compiler sees a single conditional move pattern.
    let bad_lit = (*lit_pos + lit_len > lit_total) as u32;
    let bad_off_zero = (off == 0) as u32;
    let bad_off_big = (off > post_lit) as u32;
    if (bad_lit | bad_off_zero | bad_off_big) != 0 {
        return seq_validation_error(*lit_pos, lit_len, lit_total, offset, post_lit);
    }
    unsafe {
        crate::cpu_features::wildcopy_chunks::<16>(
            lit_ptr.add(*lit_pos),
            output_base.add(cur),
            lit_len,
        );
        *lit_pos += lit_len;

        let src = output_base.add(post_lit - off);
        let dst = output_base.add(post_lit);
        crate::cpu_features::copy_match_unchecked(src, dst, off, match_len);
    }
    *dst_off = post_lit + match_len;

    // 5. Update FSE states (except on the peeled last sequence).
    //    Order: LL, ML, OF (RFC 8878 3.1.2.1.2.4). Max accuracy_log is
    //    9 + 8 + 9 = 26 bits across all three reads — one ensure_bits,
    //    three fast reads.
    //
    // Performance detail: we load all three table entries BEFORE doing any
    // bit reads. The 3 table loads are fully independent (different state
    // indices in different tables) so the OOO engine can pipeline them,
    // whereas the bit reads serialize through the shared bit container.
    // Naively calling `next_state_fast` three times interleaves load/read
    // and stalls on each load's ~4-cycle latency. Load-first shaves one
    // load-to-use latency from the critical path per iteration.
    if update_state {
        bits.ensure_bits(26);
        let ll_entry = ll_t.entry_at(*ll_state);
        let ml_entry = ml_t.entry_at(*ml_state);
        let of_entry = of_t.entry_at(*of_state);
        let ll_lb = bits.get_bits_fast(ll_entry.num_bits as u32);
        let ml_lb = bits.get_bits_fast(ml_entry.num_bits as u32);
        let of_lb = bits.get_bits_fast(of_entry.num_bits as u32);
        *ll_state = ll_entry.baseline as u32 + ll_lb;
        *ml_state = ml_entry.baseline as u32 + ml_lb;
        *of_state = of_entry.baseline as u32 + of_lb;
    }
    Ok(true)
}

// ---------------------------------------------------------------------------
// Literals section
// ---------------------------------------------------------------------------

/// Decode the literals section directly into `buf`, truncating/growing as
/// needed. Returns the real decoded-literal count. `buf` may have trailing
/// garbage past the returned length (the caller pads to +32 before the
/// sequence loop anyway).
fn decode_literals_section_into(
    r: &mut ForwardByteReader,
    huf_table: &mut Option<HufTable>,
    buf: &mut Vec<u8>,
) -> io::Result<usize> {
    let byte0 = r.read_u8()?;
    let lit_type = byte0 & 3;
    let size_format = (byte0 >> 2) & 3;

    match lit_type {
        0 => {
            // Raw literals.
            let regen_size = decode_lit_size_raw(byte0, size_format, r)?;
            let raw = r.read_bytes(regen_size)?;
            buf.clear();
            buf.extend_from_slice(raw);
            Ok(regen_size)
        }
        1 => {
            // RLE literals.
            let regen_size = decode_lit_size_raw(byte0, size_format, r)?;
            let byte = r.read_u8()?;
            buf.clear();
            buf.resize(regen_size, byte);
            Ok(regen_size)
        }
        2 | 3 => {
            // Compressed or Treeless literals.
            let (regen_size, compressed_size, four_streams) =
                decode_lit_size_compressed(byte0, size_format, r)?;

            let lit_data = r.read_bytes(compressed_size)?;
            let mut pos = 0;

            if lit_type == 2 {
                // New Huffman tree.
                let (table, consumed) = HufTable::decode_from_stream(lit_data)?;
                *huf_table = Some(table);
                pos = consumed;
            }
            // Treeless (3) reuses the previous Huffman table.

            let table = huf_table
                .as_ref()
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zstd: treeless literals without prior Huffman table"))?;

            let stream_data = &lit_data[pos..];
            // Resize to exactly `regen_size` so the inner decoders see an
            // uninitialized (but valid) region to fill. We're about to
            // overwrite every byte; the `resize` zeroes fresh bytes which
            // is fine — the wildcopy-tail padding is applied by the caller.
            buf.clear();
            buf.resize(regen_size, 0);
            if four_streams {
                super::huf::decode_literals_4stream_into(table, stream_data, buf)?;
            } else {
                super::huf::decode_literals_1stream_into(table, stream_data, buf)?;
            }
            Ok(regen_size)
        }
        _ => unreachable!(),
    }
}

fn decode_lit_size_raw(byte0: u8, size_format: u8, r: &mut ForwardByteReader) -> io::Result<usize> {
    // Per RFC 8878 §3.1.1.3.1.1 — size_format encoding for Raw/RLE literals:
    //   00 or 10 → 1-byte header, 5-bit regen size
    //   01       → 2-byte header, 12-bit regen size
    //   11       → 3-byte header, 20-bit regen size
    match size_format {
        0 | 2 => Ok((byte0 >> 3) as usize),
        1 => {
            let b1 = r.read_u8()?;
            Ok(((byte0 as usize >> 4) | ((b1 as usize) << 4)) & 0xFFF)
        }
        3 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            Ok(((byte0 as usize >> 4) | ((b1 as usize) << 4) | ((b2 as usize) << 12)) & 0xFFFFF)
        }
        _ => unreachable!(),
    }
}

fn decode_lit_size_compressed(
    byte0: u8,
    size_format: u8,
    r: &mut ForwardByteReader,
) -> io::Result<(usize, usize, bool)> {
    match size_format {
        0 => {
            // Single stream: 10-bit regen, 10-bit compressed.
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let combined = (byte0 as u32 >> 4) | ((b1 as u32) << 4) | ((b2 as u32) << 12);
            let regen = (combined & 0x3FF) as usize;
            let compressed = ((combined >> 10) & 0x3FF) as usize;
            Ok((regen, compressed, false))
        }
        1 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let combined = (byte0 as u32 >> 4) | ((b1 as u32) << 4) | ((b2 as u32) << 12);
            let regen = (combined & 0x3FF) as usize;
            let compressed = ((combined >> 10) & 0x3FF) as usize;
            Ok((regen, compressed, true))
        }
        2 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let b3 = r.read_u8()?;
            let combined = (byte0 as u32 >> 4) | ((b1 as u32) << 4) | ((b2 as u32) << 12) | ((b3 as u32) << 20);
            let regen = (combined & 0x3FFF) as usize;
            let compressed = ((combined >> 14) & 0x3FFF) as usize;
            Ok((regen, compressed, true))
        }
        3 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let b3 = r.read_u8()?;
            let b4 = r.read_u8()?;
            // 18-bit regen + 18-bit compressed = 36 bits total — must be a
            // u64 because a u32 silently drops the top 4 bits of `b4`,
            // which corrupts compressed_size for any block where it's
            // ≥ 16384 (i.e. essentially every text-heavy L1 block).
            let combined = (byte0 as u64 >> 4)
                | ((b1 as u64) << 4)
                | ((b2 as u64) << 12)
                | ((b3 as u64) << 20)
                | ((b4 as u64) << 28);
            let regen = (combined & 0x3FFFF) as usize;
            let compressed = ((combined >> 18) & 0x3FFFF) as usize;
            Ok((regen, compressed, true))
        }
        _ => unreachable!(),
    }
}

// ---------------------------------------------------------------------------
// Sequences section
// ---------------------------------------------------------------------------

fn decode_sequence_count(r: &mut ForwardByteReader) -> io::Result<usize> {
    let byte0 = r.read_u8()? as usize;
    if byte0 < 128 {
        Ok(byte0)
    } else if byte0 < 255 {
        let byte1 = r.read_u8()? as usize;
        Ok(((byte0 - 128) << 8) + byte1)
    } else {
        let lo = r.read_u8()? as usize;
        let hi = r.read_u8()? as usize;
        Ok(lo + (hi << 8) + 0x7F00)
    }
}

fn decode_fse_table_mode(
    r: &mut ForwardByteReader,
    mode: u8,
    table: &mut Option<FseTable>,
    max_symbol: u32,
    max_accuracy_log: u32,
    predefined: fn() -> FseTable,
) -> io::Result<()> {
    // Per RFC 8878 §3.1.1.3.2.1.1 — Symbol_Compression_Mode:
    //   00 → Predefined
    //   01 → RLE
    //   10 → FSE_Compressed
    //   11 → Repeat (reuse previous table from same frame)
    match mode {
        0 => {
            *table = Some(predefined());
        }
        1 => {
            let sym = r.read_u8()?;
            *table = Some(fse::fse_rle_table(sym));
        }
        2 => {
            *table = Some(FseTable::decode_table(r, max_symbol, max_accuracy_log)?);
        }
        3 => {
            if table.is_none() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zstd: repeat mode without prior FSE table",
                ));
            }
        }
        _ => unreachable!(),
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Sequence value decoding
// ---------------------------------------------------------------------------

/// Resolve offset_value to an actual offset, handling repeat offsets (RFC 8878 3.1.2.1.3).
/// Also updates the repeat offset table.
#[inline(always)]
fn resolve_offset(offset_value: u32, rep: &mut [u32; 3], lit_len: usize) -> u32 {
    if offset_value > 3 {
        // Real offset.
        let offset = offset_value - 3;
        rep[2] = rep[1];
        rep[1] = rep[0];
        rep[0] = offset;
        offset
    } else if lit_len > 0 {
        // Repeat offsets when literals_length > 0.
        match offset_value {
            1 => rep[0], // No change to rep table.
            2 => {
                let offset = rep[1];
                rep[1] = rep[0];
                rep[0] = offset;
                offset
            }
            3 => {
                let offset = rep[2];
                rep[2] = rep[1];
                rep[1] = rep[0];
                rep[0] = offset;
                offset
            }
            _ => unreachable!(),
        }
    } else {
        // Repeat offsets when literals_length == 0 (special case).
        match offset_value {
            1 => {
                let offset = rep[1];
                rep[1] = rep[0];
                rep[0] = offset;
                offset
            }
            2 => {
                let offset = rep[2];
                rep[2] = rep[1];
                rep[1] = rep[0];
                rep[0] = offset;
                offset
            }
            3 => {
                let offset = rep[0].wrapping_sub(1);
                rep[2] = rep[1];
                rep[1] = rep[0];
                rep[0] = offset;
                offset
            }
            _ => unreachable!(),
        }
    }
}

/// Cold error helper for the sequence-loop safety checks. Out-of-line so the
/// hot path only pays for one taken branch + one fall-through, not the
/// register spilling that `format!` would force inline.
#[cold]
#[inline(never)]
fn seq_validation_error(
    lit_pos: usize,
    lit_len: usize,
    lit_total: usize,
    offset: u32,
    post_lit: usize,
) -> io::Result<bool> {
    if lit_pos + lit_len > lit_total {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "zstd: literals length exceeds available literals",
        ));
    }
    Err(io::Error::new(
        io::ErrorKind::InvalidData,
        format!(
            "zstd: match offset {} exceeds available history {}",
            offset, post_lit
        ),
    ))
}

// ---------------------------------------------------------------------------
// XXHash64 (lower 32 bits) for content checksum
// ---------------------------------------------------------------------------

fn xxhash(data: &[u8]) -> u32 {
    xxhash64_public(data, 0) as u32
}

/// XXHash64 — public for use by the encoder checksum.
pub fn xxhash64_public(data: &[u8], seed: u64) -> u64 {
    xxhash64(data, seed)
}

fn xxhash64(data: &[u8], seed: u64) -> u64 {
    const PRIME1: u64 = 0x9E3779B185EBCA87;
    const PRIME2: u64 = 0xC2B2AE3D27D4EB4F;
    const PRIME3: u64 = 0x165667B19E3779F9;
    const PRIME4: u64 = 0x85EBCA77C2B2AE63;
    const PRIME5: u64 = 0x27D4EB2F165667C5;

    let len = data.len();
    let mut h: u64;
    let mut i = 0;

    if len >= 32 {
        let mut v1 = seed.wrapping_add(PRIME1).wrapping_add(PRIME2);
        let mut v2 = seed.wrapping_add(PRIME2);
        let mut v3 = seed;
        let mut v4 = seed.wrapping_sub(PRIME1);

        while i + 32 <= len {
            v1 = xxh64_round(v1, read_u64_le(data, i));
            v2 = xxh64_round(v2, read_u64_le(data, i + 8));
            v3 = xxh64_round(v3, read_u64_le(data, i + 16));
            v4 = xxh64_round(v4, read_u64_le(data, i + 24));
            i += 32;
        }

        h = v1.rotate_left(1)
            .wrapping_add(v2.rotate_left(7))
            .wrapping_add(v3.rotate_left(12))
            .wrapping_add(v4.rotate_left(18));
        h = xxh64_merge(h, v1);
        h = xxh64_merge(h, v2);
        h = xxh64_merge(h, v3);
        h = xxh64_merge(h, v4);
    } else {
        h = seed.wrapping_add(PRIME5);
    }

    h = h.wrapping_add(len as u64);

    while i + 8 <= len {
        let k = read_u64_le(data, i);
        h ^= xxh64_round(0, k);
        h = h.rotate_left(27).wrapping_mul(PRIME1).wrapping_add(PRIME4);
        i += 8;
    }

    while i + 4 <= len {
        let k = u32::from_le_bytes(data[i..i + 4].try_into().unwrap()) as u64;
        h ^= k.wrapping_mul(PRIME1);
        h = h.rotate_left(23).wrapping_mul(PRIME2).wrapping_add(PRIME3);
        i += 4;
    }

    while i < len {
        h ^= (data[i] as u64).wrapping_mul(PRIME5);
        h = h.rotate_left(11).wrapping_mul(PRIME1);
        i += 1;
    }

    // Finalize.
    h ^= h >> 33;
    h = h.wrapping_mul(PRIME2);
    h ^= h >> 29;
    h = h.wrapping_mul(PRIME3);
    h ^= h >> 32;
    h
}

#[inline(always)]
fn xxh64_round(mut acc: u64, input: u64) -> u64 {
    const PRIME1: u64 = 0x9E3779B185EBCA87;
    const PRIME2: u64 = 0xC2B2AE3D27D4EB4F;
    acc = acc.wrapping_add(input.wrapping_mul(PRIME2));
    acc = acc.rotate_left(31);
    acc.wrapping_mul(PRIME1)
}

#[inline(always)]
fn xxh64_merge(mut h: u64, v: u64) -> u64 {
    const PRIME1: u64 = 0x9E3779B185EBCA87;
    const PRIME4: u64 = 0x85EBCA77C2B2AE63;
    h ^= xxh64_round(0, v);
    h.wrapping_mul(PRIME1).wrapping_add(PRIME4)
}

#[inline(always)]
fn read_u64_le(data: &[u8], pos: usize) -> u64 {
    u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap())
}
